mapper.select:
SELECT CBL.TASK_ID taskId,
CBL.START_TIME startTime, CBL.END_TIME endTime, CBL.BATCH_RESULT batchResult FROM CHB_AUTOSEND_BATCH_LOG CBL
where CBL.TASK_ID in ('3001','3002','3071')
CBL.TASK_ID = #{taskId}
AND to_char(CBL.START_TIME,'yyyy-MM-dd') <= #{date,jdbcType=VARCHAR} AND to_char(CBL.END_TIME,'yyyy-MM-dd') >=#{date,jdbcType=VARCHAR}
ORDER BY CBL.START_TIME DESC
